#Requires -Version 7.0
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$StoreReceipt,
    [Parameter(Mandatory)][string]$DesignationSha
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$hostPath = 'C:\Program Files\PowerShell\7\pwsh.exe'
if (-not [Environment]::Is64BitProcess -or (Get-Process -Id $PID).Path -ine $hostPath) { throw 'HOLD_UNAPPROVED_HOST' }
$env:PSModulePath = Join-Path $PSHOME 'Modules'
Import-Module (Join-Path $PSHOME 'Modules\Microsoft.PowerShell.Security\Microsoft.PowerShell.Security.psd1')
$signature = Get-AuthenticodeSignature -LiteralPath $hostPath
if ($signature.Status -ne 'Valid' -or
    $signature.SignerCertificate.Subject -notmatch '(^|,\s*)O=Microsoft Corporation(,|$)') { throw 'HOLD_HOST_SIGNATURE' }

if ($StoreReceipt -cnotmatch '^[a-f0-9]{16}:[a-f0-9]{32}:[a-f0-9]{64}$' -or
    $DesignationSha -cnotmatch '^[a-f0-9]{64}$') { throw 'HOLD_APPROVAL_RECEIPT_FORMAT' }
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
try {
    $expectedSid = ([Security.Principal.NTAccount]::new([Environment]::MachineName, 'windows')).Translate([Security.Principal.SecurityIdentifier])
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    if (-not $expectedSid.Equals($identity.User) -or
        -not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'HOLD_SIGNER_TOKEN' }
    $sid = $identity.User.Value
} finally { $identity.Dispose() }
$embeddedAssembly = ''
$type = [Reflection.Assembly]::Load([Convert]::FromBase64String($embeddedAssembly)).GetType('LimitlessVerifierStorePreparation', $true)
try { $recordBytes = $type::ReadDesignation($sid, $StoreReceipt, $DesignationSha) }
catch {
    $cause = $_.Exception.GetBaseException()
    if ($cause -is [ComponentModel.Win32Exception]) { throw ("HOLD_RECORD_READ_{0}" -f $cause.NativeErrorCode) }
    if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
    throw 'HOLD_RECORD_READ'
}
$utf8 = [Text.UTF8Encoding]::new($false, $true)
$record = $utf8.GetString($recordBytes) | ConvertFrom-Json -AsHashtable
$base = 'F:\study\codex\Project-Limitless\Temp\DiscordUsageDiagnostics20261026'
$candidate = Join-Path $base 'StagingVerifierRelease-3f674efb\candidate\Limitless.StagingVerifier.exe'
$checker = Join-Path $base 'Worktree\Tools\DiscordV2\StagingDraft\Test-ApprovedSigningKey.ps1'
$checkerSha = 'ab57366eef3eefe1e74c6f50cebf440c815d88e6ef8aada2ffa66c616448b24f'
if ($record.Schema -cne 'LIMITLESS_SIGNING_ACCOUNT_DESIGNATION_V1' -or
    $record.Approval -cne 'ISSUE66_SIGNER_DESIGNATION_RECORD_1' -or
    $record.Scope -cne 'ACCOUNT_DESIGNATION_ONLY' -or $record.Account -cne 'windows' -or
    $record.AccountSid -cne $sid -or $record.KeyCheckScriptPath -ine $checker -or
    $record.KeyCheckScriptSha256 -cne $checkerSha -or $record.CandidatePath -ine $candidate -or
    $record.CandidateSha256 -cne '145f3921e88ab2caba98afd4c5bb39eb7f9706aa6ad5e3fca5d5891f9f73adbb' -or
    $record.CertificateThumbprint -cne '437423567AD4B703578F231E34A06592B38DB4EB' -or
    $record.CertificateDerSha256 -cne '7dba5310d6ded0035595e5e7ab8b8b73422f2925b49c633426995c322940672c' -or
    $record.RsaSpkiSha256 -cne '2a6d0a7d31e7642df209b6cbe12fa628500663f540eb6bd557cac2aca2d31f7c') {
    throw 'HOLD_DESIGNATION_BINDING'
}

$exeSha = $record.CandidateSha256
$thumb = $record.CertificateThumbprint
$toolOrigin = 'E:\Windows Kits\10\bin\10.0.26100.0\x64\signtool.exe'
$toolSha = '0d0189af3356554a462c2a60d0d59f6006b68d743f5c0cc93c530b083706f075'
$targetName = 'Limitless.StagingVerifier.exe'
$toolName = 'signtool.exe'
function Get-ByteSha([byte[]]$b) {
    [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($b)).ToLowerInvariant()
}
function Read-PinnedInput([string]$path, [string]$expected) {
    $stream = [IO.File]::Open($path, 'Open', 'Read', 'Read')
    try {
        $size = $stream.Length
        if ($size -lt 1 -or $size -gt 16777216) { throw 'HOLD_INPUT_SIZE' }
        $b = [byte[]]::new([int]$size)
        $stream.ReadExactly($b)
        if ((Get-ByteSha $b) -cne $expected) { throw 'HOLD_SIGN_INPUT_SHA' }
        return ,$b
    } finally { $stream.Dispose() }
}
function Assert-WorkspaceSha($space, [string]$name, [string]$expected) {
    $file = $space.OpenVerifiedFile($name)
    try {
        if ([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($file)).ToLowerInvariant() -cne $expected) {
            throw 'HOLD_PROTECTED_COPY_SHA'
        }
    } finally { $file.Dispose() }
}

$exeBytes = Read-PinnedInput $candidate $exeSha
$toolBytes = Read-PinnedInput $toolOrigin $toolSha
$cert = Get-Item -LiteralPath "Cert:\LocalMachine\My\$thumb"
try {
    $nowLocal = Get-Date
    if ($cert.Thumbprint -cne $thumb -or
        $cert.GetCertHashString([Security.Cryptography.HashAlgorithmName]::SHA256).ToLowerInvariant() -cne $record.CertificateDerSha256 -or
        -not $cert.HasPrivateKey -or $nowLocal -lt $cert.NotBefore -or $nowLocal -ge $cert.NotAfter) {
        throw 'HOLD_SIGNING_CERTIFICATE'
    }
} finally { $cert.Dispose() }

$start = [DateTimeOffset]::UtcNow
$end = $start.AddMinutes(5)
$workspaceType = $type.GetNestedType('SigningWorkspace')
try { $workspace = [Activator]::CreateInstance($workspaceType, [object[]]@($sid, $start, $end)) }
catch {
    $cause = $_.Exception.GetBaseException()
    if ($cause -is [ComponentModel.Win32Exception]) { throw ("HOLD_WORKSPACE_NATIVE_{0}" -f $cause.NativeErrorCode) }
    if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
    throw 'HOLD_WORKSPACE_CREATE'
}
try {
    $workspace.CopyVerifiedBytes($targetName, $exeBytes)
    $workspace.CopyVerifiedBytes($toolName, $toolBytes)
    $target = Join-Path $workspace.DirectoryPath $targetName
    $tool = Join-Path $workspace.DirectoryPath $toolName
    Assert-WorkspaceSha $workspace $targetName $exeSha
    $toolHandle = $workspace.OpenVerifiedFile($toolName)
    try {
        $observedToolSha = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($toolHandle)).ToLowerInvariant()
        $toolSig = Get-AuthenticodeSignature -LiteralPath $tool
        if ($observedToolSha -cne $toolSha -or $toolSig.Status -ne 'Valid' -or
            $toolSig.SignerCertificate.Subject -notmatch '(^|,\s*)O=Microsoft Corporation(,|$)' -or
            (Get-AuthenticodeSignature -LiteralPath $target).Status -ne 'NotSigned') {
            throw 'HOLD_SIGN_PRECHECK'
        }
        function Invoke-SdkTool([string[]]$arguments, [string]$failure) {
            $info = [Diagnostics.ProcessStartInfo]::new()
            $info.FileName = $tool
            $info.WorkingDirectory = $workspace.DirectoryPath
            $info.UseShellExecute = $false
            $info.Environment['PATH'] = [Environment]::SystemDirectory
            foreach ($arg in $arguments) { $info.ArgumentList.Add($arg) }
            $process = [Diagnostics.Process]::Start($info)
            if ($null -eq $process) { throw $failure }
            try {
                $process.WaitForExit()
                if ($process.ExitCode -ne 0) { throw $failure }
            } finally { $process.Dispose() }
        }
        $workspace.Check()
        if ([DateTimeOffset]::UtcNow -ge $end) { throw 'HOLD_SIGN_WINDOW' }
        Invoke-SdkTool @('sign','/sm','/s','My','/sha1',$thumb,'/fd','SHA256',$target) 'HOLD_SIGN_NO_RETRY'
        $signed = $workspace.OpenVerifiedFile($targetName)
        try {
            Invoke-SdkTool @('verify','/pa','/all',$target) 'HOLD_AUTHENTICODE_VERIFY'
            $signature = Get-AuthenticodeSignature -LiteralPath $target
            if ($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Thumbprint -cne $thumb) {
                throw 'HOLD_SIGNER_THUMBPRINT'
            }
            $leaf = $signature.SignerCertificate
            $rsa = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($leaf)
            try {
                $eku = @($leaf.Extensions | Where-Object { $_ -is [Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension] } |
                    ForEach-Object EnhancedKeyUsages | ForEach-Object Value)
                $at = Get-Date
                if ($null -eq $rsa -or $leaf.GetCertHashString([Security.Cryptography.HashAlgorithmName]::SHA256).ToLowerInvariant() -cne $record.CertificateDerSha256 -or
                    (Get-ByteSha ($rsa.ExportSubjectPublicKeyInfo())) -cne $record.RsaSpkiSha256 -or
                    $eku -notcontains '1.3.6.1.5.5.7.3.3' -or $at -lt $leaf.NotBefore -or $at -ge $leaf.NotAfter) {
                    throw 'HOLD_SIGNER_POLICY'
                }
            } finally { if ($null -ne $rsa) { $rsa.Dispose() } }
            $after = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($signed)).ToLowerInvariant()
            if ($after -ceq $exeSha) { throw 'HOLD_IMAGE_UNCHANGED' }
            $workspace.Check()
            'SIGNING_AUTHENTICODE_VERIFIED'
            "UNSIGNED_EXE_SHA256=$exeSha"
            "SIGNED_EXE_SHA256=$after"
            "SIGNED_EXE_PATH=$target"
        } finally { $signed.Dispose() }
    } finally { $toolHandle.Dispose() }
} finally { $workspace.Dispose() }
